<template><div><LoadingState v-if='loading'/><ErrorState v-else-if='error' :message='error'/><BaseCard v-else><h2 class='text-xl mb-2'>Prontuário #{{ route.params.id }}</h2><pre class='text-xs whitespace-pre-wrap'>{{ JSON.stringify(record,null,2) }}</pre><router-link :to='`/medical-records/${route.params.id}/ai`' class='text-blue-600'>Ir para IA</router-link></BaseCard></div></template>
<script setup>import { onMounted,ref } from 'vue';import { useRoute } from 'vue-router';import { medicalRecordService } from '../services/medicalRecordService';import LoadingState from '../components/LoadingState.vue';import ErrorState from '../components/ErrorState.vue';import BaseCard from '../components/BaseCard.vue';
const route=useRoute();const loading=ref(false),error=ref(''),record=ref(null);onMounted(async()=>{loading.value=true;try{record.value=await medicalRecordService.getById(route.params.id)}catch{error.value='Erro ao carregar prontuário'}finally{loading.value=false}})
</script>
